<?php
require __DIR__.'/config.php';manager_only();$date=queryv('tanggal',date('Y-m-d'));if(!valid_date($date))$date=date('Y-m-d');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_post();$id=(int)post('id');$attendance=post('attendance');$date=post('tanggal');if(!valid_date($date))$date=date('Y-m-d');
if(!in_array($attendance,['belum','hadir','izin','tidak_hadir'],true))notice('Status tidak valid.','danger');else{$q=db()->prepare('UPDATE schedules SET attendance=?, attendance_at=IF(?="belum",NULL,NOW()) WHERE id=?');$q->execute([$attendance,$attendance,$id]);audit('catat_absensi','Jadwal #'.$id.' · '.$attendance);notice('Absensi berhasil diperbarui.');}go('kehadiran.php',['tanggal'=>$date]);}
$q=db()->prepare("SELECT s.*,i.name imam_name FROM schedules s JOIN imams i ON i.id=s.imam_id WHERE prayer_date=? ORDER BY FIELD(prayer,'Subuh','Dzuhur','Ashar','Maghrib','Isya')");$q->execute([$date]);$rows=$q->fetchAll();
$pageTitle='Absensi';$active='kehadiran';require __DIR__.'/partials/admin_header.php';
?><div class="page-head"><div><div class="section-eyebrow">KONFIRMASI KEHADIRAN PENGURUS</div><h1>Absensi imam</h1><p>Kesediaan imam tidak otomatis dihitung sebagai kehadiran. Pengurus mengisi hasil aktual.</p></div></div><div class="card"><form method="get" class="filter-panel"><label>Tanggal<input type="date" name="tanggal" value="<?=h($date)?>"></label><button class="btn primary">Tampilkan</button></form><div class="table-scroll"><table class="data-table"><thead><tr><th>Waktu</th><th>Jam</th><th>Imam</th><th>Kesediaan</th><th>Absensi sekarang</th><th>Perbarui</th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><?=h($s['prayer'])?></td><td><?=h(substr($s['start_time'],0,5))?></td><td><?=h($s['imam_name'])?></td><td><?=pill(status_confirmation($s['confirmation']))?></td><td><?=pill(status_attendance($s['attendance']))?></td><td><form method="post" class="flex"><?=csrf_input()?><input type="hidden" name="id" value="<?=h($s['id'])?>"><input type="hidden" name="tanggal" value="<?=h($date)?>"><select name="attendance" style="width:128px"><?php foreach(['belum'=>'Belum diisi','hadir'=>'Hadir','izin'=>'Izin','tidak_hadir'=>'Tidak hadir'] as $k=>$v):?><option value="<?=h($k)?>" <?=$s['attendance']===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select><button class="btn small primary">Simpan</button></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td class="empty" colspan="6">Belum ada jadwal pada tanggal ini.</td></tr><?php endif;?></tbody></table></div></div>
<?php require __DIR__.'/partials/admin_footer.php'; ?>
